'use strict';
const C=MaruCore,app=document.querySelector('#app'),ANIMALS=['🐰','🐻','🦊','🐼','🐨','🐯','🐸','🦁','🐱','🐶'],COLORS=['#f9dbd9','#f4e3ae','#d9e6cd','#dce3f2','#ead9eb','#f9dfc5','#d0eadc','#f5dabb','#d5eaf5','#f3d8e5'];
let cloud=null,cloudReady=false,cloudState='loading',cloudError='';
let view='loading',classId=null,records={},setupNames=null,voice=true,musicEnabled=true,storageOK=true,pendingAction=null;
try{const prefs=JSON.parse(localStorage.getItem('maru-classroom-prefs'));voice=prefs?.voice!==false;musicEnabled=prefs?.music!==false}catch{}
const music=MaruMusic({enabled:musicEnabled});
function savePreferences(){try{localStorage.setItem('maru-classroom-prefs',JSON.stringify({voice,music:musicEnabled}))}catch{}}
document.addEventListener('pointerdown',()=>music.unlock(),{capture:true});
document.addEventListener('keydown',()=>music.unlock(),{capture:true});
document.addEventListener('visibilitychange',()=>music.setActive(!document.hidden));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function record(id=classId){return records[id]||(records[id]=C.loadClass(localStorage,id))}
function save(){try{C.saveClass(localStorage,classId,record())}catch{storageOK=false}cloud?.save(classId,record())}
function session(){return record().session}function turn(){return session().turns[session().index]}function mission(){return C.BY_ID[turn().mission]}
function toast(text){const e=document.querySelector('#toast');e.textContent=text;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',2500)}
let voiceToken=0,finishClip=null,voiceJobs=0;const narrator=new Audio();narrator.volume=.86;narrator.preload='auto';
function syncVoiceControls(){
 document.querySelector('#sound').dataset.state=voiceJobs?'playing':'idle';
 document.body.classList.toggle('speaking',voiceJobs>0);
 music.setSpeaking(voiceJobs>0);
 document.querySelector('#music').dataset.ducked=String(voiceJobs>0);
 // Speech never disables Ready, Next, or game controls.
}
function stopVoice(){voiceToken++;narrator.pause();window.speechSynthesis?.cancel();const done=finishClip;finishClip=null;done?.();voiceJobs=0;syncVoiceControls()}
async function play(keys,force=false){
 stopVoice();if(!voice&&!force)return;
 const token=voiceToken;voiceJobs=1;syncVoiceControls();
 try{for(const key of keys){
  if(token!==voiceToken)return;
  if(key.startsWith('local-name:')){
   const localVoice=window.speechSynthesis?.getVoices().find(v=>v.localService&&/^en/i.test(v.lang));
   if(localVoice)await new Promise(resolve=>{
    let timer;const utterance=new SpeechSynthesisUtterance(key.slice(11));
    const done=()=>{clearTimeout(timer);resolve()};finishClip=done;
    utterance.voice=localVoice;utterance.lang=localVoice.lang;utterance.rate=.94;utterance.pitch=1.08;utterance.volume=.86;
    utterance.onend=done;utterance.onerror=done;timer=setTimeout(()=>{window.speechSynthesis.cancel();done()},8000);
    window.speechSynthesis.speak(utterance);
   });
   continue;
  }
  const src=key.startsWith('name:')?window.MARU_NAMES?.[key.slice(5)]:window.MARU_AUDIO?.[key];if(!src)continue;
  await new Promise(resolve=>{
   let timer;const done=()=>{clearTimeout(timer);resolve()};finishClip=done;
   narrator.onended=done;narrator.onerror=done;narrator.src=src;
   timer=setTimeout(done,15000);
   narrator.play().catch(done);
  });
 }}finally{if(token===voiceToken){narrator.pause();finishClip=null;voiceJobs=0;syncVoiceControls()}}
}
function announce(force=false){const name=session().players[turn().player].name;const key=name.trim().toLowerCase();return play(window.MARU_NAMES?.[key]?['name:'+key]:['local-name:'+name,'turn'],force)}
function sayChoice(id,success=false){play(['choice:'+id,...(success?['nice']:[])])}
function confirmBox(title,body,label,action){stopVoice();document.querySelector('#confirm-title').textContent=title;document.querySelector('#confirm-body').textContent=body;document.querySelector('#confirm-yes').textContent=label;pendingAction=action;document.querySelector('#confirm-dialog').showModal()}
function avatar(i,big=false){return `<span class="avatar ${big?'big':''}" style="--avatar:${COLORS[i%COLORS.length]}">${ANIMALS[i%ANIMALS.length]}</span>`}
function flag(color='red'){return `<span class="flag-art" role="img" aria-label="${color==='red'?'Japan flag':'A different flag'}"><i style="background:${color==='red'?'#d75b50':color==='blue'?'#6c9dcb':'#78a66b'}"></i></span>`}
function item(id){const v=C.ITEMS[id];if(id==='redleaf'||id==='yellowleaf')return `<span class="emoji-art">${sticker(id)}</span>`;if(v.map)return `<img class="continent-map" src="images/map-${v.map}.svg" alt="${esc(v.label)} map" draggable="false">`;if(v.photo)return `<img src="images/${v.photo}.png" alt="${esc(v.label)}" draggable="false">`;if(['flag','blueflag','greenflag'].includes(id))return flag(id==='flag'?'red':id==='blueflag'?'blue':'green');if(v.color)return `<span class="color-art" style="background:${v.color}" role="img" aria-label="${v.label}"></span>`;return `<span class="emoji-art" role="img" aria-label="${v.label}">${v.icon}</span>`}
function sticker(id){if(C.ITEMS[id]?.map)return `<img class="map-sticker" src="images/map-${C.ITEMS[id].map}.svg" alt="${esc(C.ITEMS[id].label)} map">`;if(id==='redleaf'||id==='yellowleaf')return `<svg class="leaf ${id==='redleaf'?'red':'yellow'}" viewBox="0 0 100 110" role="img" aria-label="${id==='redleaf'?'Red maple leaf':'Yellow maple leaf'}"><path fill="${id==='redleaf'?'#ff0000':'#ffdd00'}" d="M50 3 L58 24 L66 19 L62 44 L77 31 L79 42 L95 38 L88 56 L97 61 L67 83 L72 93 L53 89 L54 107 L47 107 L48 89 L28 93 L33 83 L3 61 L12 56 L5 38 L21 42 L23 31 L38 44 L34 19 L42 24 Z"/></svg>`;return C.ITEMS[id]?.icon||'★'}
function mosaic(){return `<div class="season-hero"><img src="images/season-hero-v6.png" alt="Maru in the middle of four seasons: cherry blossoms, fireworks, autumn leaves and snow"><span class="season-label spring">Spring</span><span class="season-label summer">Summer</span><span class="season-label autumn">Autumn</span><span class="season-label winter">Winter</span></div>`}
function fit(){const f=document.querySelector('#viewport');if(!app.offsetHeight)return;app.style.setProperty('--board-scale',Math.max(.1,Math.min(1.2,(f.clientWidth-32)/1168,(f.clientHeight-12)/app.offsetHeight)))}
function render(){document.querySelector('#class-badge').innerHTML='';document.querySelector('#reset').disabled=!cloudReady;document.querySelector('#reset').textContent='↻ Reset game';document.querySelector('#sound').textContent=voice?'🔊 Voice on':'🔇 Voice off';document.querySelector('#sound').setAttribute('aria-pressed',String(voice));document.querySelector('#music').textContent=musicEnabled?'♫ Music on':'♫ Music off';document.querySelector('#music').setAttribute('aria-pressed',String(musicEnabled));({loading:renderLoading,setup:renderSetup,game:renderGame,result:renderResult}[view])();syncVoiceControls();fit()}
async function goSetup(){if(!cloudReady)return;stopVoice();try{await cloud.flush();await cloud.loadClass(classId);setupNames=null;view='setup';render()}catch{toast('Connect to load your saved players.')}}
function setupError(names){if(!names.length||names.length>C.MAX_PLAYERS)return 'Choose 1–10 players.';if(names.some(n=>!n.trim()))return 'Give every player a name.';if(new Set(names.map(n=>n.trim().toLowerCase())).size!==names.length)return 'Use a different name for each player.';return '';}
function saveSetup(){const names=setupNames.map(n=>n.trim()),error=setupError(names);const e=app.querySelector('#setup-error');if(e)e.textContent=error;const start=app.querySelector('#start');if(start)start.disabled=!!error;if(error)return false;record().roster=[...names];record().attendance=[...names];save();return true;}
async function copyGameLink(){try{await cloud.flush();const link=new URL(location.href);link.search='';link.searchParams.set('room',classId);await navigator.clipboard.writeText(link.href);toast('Game link copied. Open it on another computer.')}catch{toast('Use this page’s address to reopen this game.')}}
function renderSetup(){const r=record();if(!setupNames)setupNames=[...r.roster];const count=setupNames.length;
 app.innerHTML=`<section class="hero player-hero"><div><span class="pill">LET'S GO TO JAPAN</span><h1>Hello, <span class="accent">explorers!</span></h1><p>Who’s playing with Maru?</p><div class="howto"><span>🧩 Match</span><span>🐾 Explore</span><span>🎨 Create</span></div></div>${mosaic()}</section><form id="players-form"><div class="player-heading"><h2>Set up your players.</h2><span>${count} / 10 players · 1 turn each</span></div><div class="player-input-grid">${setupNames.map((name,i)=>`<div class="player-input-card">${avatar(i)}<label for="player-${i}">Player ${i+1}<input id="player-${i}" data-player="${i}" aria-label="Player ${i+1} name" value="${esc(name)}" maxlength="24" autocomplete="off" spellcheck="false"></label><button class="remove-player" type="button" data-remove="${i}" aria-label="Remove player ${i+1}" ${count===1?'disabled':''}>×</button></div>`).join('')}</div><div class="player-actions"><button class="secondary" id="add-player" type="button" ${count>=C.MAX_PLAYERS?'disabled':''}>＋ Add player</button><span id="setup-error" role="status">${setupError(setupNames)}</span><button class="primary" id="start" type="submit" ${setupError(setupNames)?'disabled':''}>Let’s play! →</button></div></form><div class="player-saved-actions">${r.session&&!r.session.finished?'<button class="secondary" id="resume">▶ Continue game</button>':''}${r.session?.finished?'<button class="secondary" id="last-results">🏆 Last results</button>':''}<button class="quiet" id="copy-game">↗ Copy game link</button><span>Scores are saved on this device.</span></div>`;
 app.querySelectorAll('[data-player]').forEach(input=>input.oninput=()=>{setupNames[+input.dataset.player]=input.value;saveSetup()});
 app.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{setupNames.splice(+b.dataset.remove,1);saveSetup();render()});
 app.querySelector('#add-player').onclick=()=>{if(setupNames.length>=C.MAX_PLAYERS)return;let n=setupNames.length+1;while(setupNames.some(x=>x.trim().toLowerCase()==='player '+n))n++;setupNames.push('Player '+n);saveSetup();render();const input=app.querySelector('[data-player="'+(setupNames.length-1)+'"]');input.focus();input.select()};
 app.querySelector('#players-form').onsubmit=e=>{e.preventDefault();if(!saveSetup())return;if(r.session&&!r.session.finished)confirmBox('Start a new game?','Replace this unfinished game? Your saved results will stay.','Start new game',startGame);else startGame()};
 app.querySelector('#resume')?.addEventListener('click',()=>{view='game';render();turn().called?play([(turn().done?'fact:':'mission:')+mission().id]):announce()});
 app.querySelector('#last-results')?.addEventListener('click',()=>{view='result';render()});app.querySelector('#copy-game').onclick=copyGameLink;
}
function startGame(){stopVoice();let r=record();if(r.attendance.length<1||r.attendance.length>C.MAX_PLAYERS)return;let players=r.attendance.map(name=>({name,score:0,completed:0}));r.session={format:C.FORMAT,id:crypto.randomUUID(),players,turns:C.makeSchedule(players),index:0,startedAt:Date.now(),finished:false};save();view='game';render();announce()}
function scoreboard(){let s=session(),current=s.finished?-1:turn().player;return `<aside class="scoreboard ${s.players.length>8?'ten-players':''}"><h3>⭐ Our players</h3>${s.players.map((p,i)=>`<div class="score-row ${i===current?'current':''}">${avatar(i)}<div class="score-name">${esc(p.name)}<small>${p.completed?'✓ Done':'○ Ready'}</small></div><b>${p.score}</b></div>`).join('')}<p class="score-note">1 turn for every explorer</p></aside>`}
const MODE={quiz:['🖼️','Picture clue'],spot:['🔍','Find Maru'],maze:['🐾','Maru’s maze'],match:['🧩','Match it'],decorate:['🎨','Season studio'],flag:['🇯🇵','Flag studio']};
function renderGame(){let s=session(),t=turn(),m=mission(),p=s.players[t.player];app.innerHTML=`<div class="game-head"><div><span class="pill">OUR GAME · ONE TURN EACH</span><h1>${MODE[m.type][0]} ${MODE[m.type][1]}</h1></div><div class="progress-wrap">${s.index+1} / ${s.turns.length}<div class="progress"><div style="width:${(s.index+(t.done?1:0))/s.turns.length*100}%"></div></div></div></div><div class="game-layout"><section class="play-card" aria-label="Current mission">${!t.called?`<div class="turn-call"><span class="pill">WHO'S NEXT?</span>${avatar(t.player,true)}<h2>${esc(p.name)},<br><span>it’s your turn!</span></h2><p>Come and help Maru.</p><div class="call-actions"><button class="listen" id="call-listen">🔊 Your turn</button><button class="primary" id="ready">I’m ready! →</button></div></div>`:`<div class="question-top"><div class="turn-label">${avatar(t.player)}<strong>${esc(p.name)}</strong><span> · Your turn!</span><button class="listen" id="listen">🔊 Listen</button></div><div class="question-line"><h2>${esc(m.title)}</h2>${m.topic==='flag'&&m.type==='quiz'?flag():''}</div></div><div class="activity">${activityHTML(m,t)}</div><div class="response-zone ${t.done?'answered':''}">${t.done?`<div class="response-copy" role="status"><strong>⭐ +${t.points} · Great work!</strong><span>${esc(m.fact)}</span></div><button class="primary" id="next">${s.index===s.turns.length-1?'🏆 Our results':'Next explorer →'}</button>`:`<span class="tap-hint" id="hint" role="status">${{quiz:'☝ Tap a picture.',spot:'☝ Look for the red circle.',maze:'↑ ↓ ← → Help Maru move.',match:'☝ Picture → partner',decorate:'☝ Choose → place · or drag',flag:'🎨 Choose a color → paint'}[m.type]}</span><span class="reward">⭐ Up to 10</span>`}</div>`}</section>${scoreboard()}</div>`;
if(!t.called){app.querySelector('#call-listen').onclick=()=>announce(true);app.querySelector('#ready').onclick=()=>{t.called=true;save();render();play(['mission:'+m.id])};return}app.querySelector('#listen').onclick=()=>play([t.done?'fact:'+m.id:'mission:'+m.id],true);if(t.done){app.querySelector('#next').onclick=nextTurn;return}bindActivity(m,t)}
function activityHTML(m,t){let d=t.data;if(m.type==='quiz')return `<div class="picture-answers">${d.order.map(id=>`<button class="picture-answer ${d.wrong.includes(id)?'wrong':''} ${t.done&&id===m.answer?'correct':''}" data-answer="${id}" aria-label="Choose ${C.ITEMS[id].label}" ${t.done||d.wrong.includes(id)?'disabled':''}><div class="card-image">${item(id)}</div><div class="card-label">${C.ITEMS[id].label}${t.done&&id===m.answer?' ✓':''}</div></button>`).join('')}</div>`;
if(m.type==='spot'){let points={spring:[62.4,53.7],summer:[37.6,58.6],autumn:[61.6,51.3],winter:[61,53]},[x,y]=points[m.season];return `<div class="spot-wrap"><div class="spot-scene" id="spot-scene"><img src="images/${m.season}.png" alt="Maru in ${m.season}" style="transform:${d.mirror?'scaleX(-1)':'none'}" draggable="false"><button id="spot-target" class="spot-target ${t.done?'revealed':''}" aria-label="Red circle on Maru" style="left:${d.mirror?100-x:x}%;top:${y}%" ${t.done?'disabled':''}>${t.done?'✓':''}</button></div></div>`}
if(m.type==='maze')return `<div class="maze-layout"><div class="maze" role="group" aria-label="Maru's maze">${d.grid.map((row,y)=>row.map((wall,x)=>{let goal=C.MAZE_EXITS.findIndex(e=>e.x===x&&e.y===y),exit=goal>=0?d.exits[goal]:null;return wall?'<span class="maze-wall"></span>':`<button class="maze-cell ${exit?'exit':''} ${d.x===x&&d.y===y?'cat-here':''}" data-x="${x}" data-y="${y}" aria-label="${exit?'Exit '+C.ITEMS[exit].label:'Path '+x+', '+y}" ${t.done?'disabled':''}>${exit?item(exit):''}${d.x===x&&d.y===y?'<span class="maru-token">🐱</span>':''}</button>`}).join('')).join('')}</div><div class="maze-controls"><span class="pill">HELP MARU!</span><div class="arrow-pad"><button data-move="0,-1" aria-label="Move up">↑</button><button data-move="-1,0" aria-label="Move left">←</button><button data-move="0,1" aria-label="Move down">↓</button><button data-move="1,0" aria-label="Move right">→</button></div><p>Arrows or keyboard</p><div class="maze-legend">${d.exits.map(k=>`<span>${sticker(k)}<small>${C.ITEMS[k].label}</small></span>`).join('')}</div></div></div>`;
if(m.type==='match')return `<div class="match-board"><svg class="match-lines" viewBox="0 0 690 288" aria-hidden="true">${d.pairs.map(k=>`<path d="M260 ${d.left.indexOf(k)*96+44} C335 ${d.left.indexOf(k)*96+44},355 ${d.right.indexOf(k)*96+44},430 ${d.right.indexOf(k)*96+44}"/>`).join('')}</svg><div class="match-column">${d.left.map(k=>`<button class="match-card ${d.selected===k?'selected':''} ${d.pairs.includes(k)?'matched':''}" data-left="${k}" aria-label="Picture ${C.ITEMS[k].label}" aria-pressed="${d.selected===k}" ${t.done||d.pairs.includes(k)?'disabled':''}>${item(k)}<span>${C.ITEMS[k].label}</span><i>●</i></button>`).join('')}</div><div></div><div class="match-column">${d.right.map(k=>`<button class="match-card feature ${d.pairs.includes(k)?'matched':''}" data-right="${k}" aria-label="Partner ${C.ITEMS[C.FEATURES[k]].label}" ${t.done||d.pairs.includes(k)?'disabled':''}><i>●</i><b>${sticker(C.FEATURES[k])}</b><span>${C.ITEMS[C.FEATURES[k]].label}</span></button>`).join('')}</div></div>`;
if(m.type==='decorate'){let palette={spring:['blossom','snow','redleaf'],summer:['fireworks','goldfirework','blossom'],autumn:['redleaf','yellowleaf','snow'],winter:['snow','ski','fireworks']}[m.season],spots=[[18,25],[79,27],[20,78],[80,79]];return `<div class="studio"><div class="decoration-scene"><img src="images/${m.season}.png" alt="Maru's ${m.season} scene" draggable="false">${m.recipe.map((k,i)=>`<button class="decoration-spot ${d.placed.includes(i)?'placed':''}" data-slot="${i}" style="left:${spots[i][0]}%;top:${spots[i][1]}%" aria-label="${C.ITEMS[k].label} spot ${i+1}" ${t.done||d.placed.includes(i)?'disabled':''}>${sticker(k)}</button>`).join('')}</div><div class="decoration-palette"><span>Pick & place</span>${palette.map(k=>`<button class="palette-item ${d.selected===k?'selected':''}" data-decoration="${k}" draggable="${!t.done}" aria-label="Use ${C.ITEMS[k].label}" aria-pressed="${d.selected===k}" ${t.done?'disabled':''}><b>${sticker(k)}</b><small>${C.ITEMS[k].label}</small></button>`).join('')}<span>${d.placed.length} / ${m.recipe.length}</span></div></div>`}
if(m.type==='flag')return `<div class="flag-studio"><div class="paint-flag"><button id="paint-background" aria-label="Paint the background" style="background:${d.background?'#fffdf7':'#dedfd9'}" ${t.done||d.background?'disabled':''}></button><button id="paint-circle" aria-label="Paint the circle" style="background:${d.circle?'#dc6354':'#bfc5bb'}" ${t.done||d.circle?'disabled':''}></button></div><div class="paint-palette"><span>Pick a color</span>${['white','red','blue','yellow'].map(k=>`<button data-color="${k}" class="color-button ${d.selected===k?'selected':''}" aria-label="Use ${C.ITEMS[k].label}" aria-pressed="${d.selected===k}" ${t.done?'disabled':''}>${item(k)}<small>${C.ITEMS[k].label}</small></button>`).join('')}</div></div>`;return ''}
function bindActivity(m,t){let d=t.data;app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{let id=b.dataset.answer;if(id===m.answer)complete();else if(!d.wrong.includes(id)){d.wrong.push(id);mistake('Try another picture.')}});app.querySelector('#spot-target')?.addEventListener('click',e=>{e.stopPropagation();complete('circle')});app.querySelector('#spot-scene')?.addEventListener('click',()=>mistake('Look for the red circle.'));app.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(...b.dataset.move.split(',').map(Number)));app.querySelectorAll('[data-x]').forEach(b=>b.onclick=()=>{let dx=+b.dataset.x-d.x,dy=+b.dataset.y-d.y;if(Math.abs(dx)+Math.abs(dy)===1)move(dx,dy);else toast('One step at a time. Use the arrows!')});app.querySelectorAll('[data-left]').forEach(b=>b.onclick=()=>{d.selected=b.dataset.left;save();render();sayChoice(d.selected)});app.querySelectorAll('[data-right]').forEach(b=>b.onclick=()=>{if(!d.selected){toast('Pick a picture on the left first.');play(['pair']);return}let choice=C.FEATURES[b.dataset.right];if(d.selected===b.dataset.right){d.pairs.push(d.selected);d.selected=null;if(d.pairs.length===m.keys.length)complete(choice);else{save();render();sayChoice(choice)}}else mistake('Try a different partner.',choice)});app.querySelectorAll('[data-decoration]').forEach(b=>{b.onclick=()=>{d.selected=b.dataset.decoration;save();render();sayChoice(d.selected)};b.ondragstart=e=>{d.selected=b.dataset.decoration;save();sayChoice(d.selected);e.dataTransfer.setData('text/plain',b.dataset.decoration);e.dataTransfer.effectAllowed='copy'}});app.querySelectorAll('[data-slot]').forEach(b=>{b.onclick=()=>decorate(+b.dataset.slot,d.selected);b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();decorate(+b.dataset.slot,e.dataTransfer.getData('text/plain'))}});app.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{d.selected=b.dataset.color;save();render();sayChoice(d.selected)});app.querySelector('#paint-background')?.addEventListener('click',()=>paint('background'));app.querySelector('#paint-circle')?.addEventListener('click',()=>paint('circle'))}
function mistake(text,choice){if(turn().done)return;turn().mistakes++;save();render();toast(text);choice?sayChoice(choice):play(['retry'])}
function complete(choice){let t=turn();if(t.done)return;t.done=true;t.points=Math.max(4,10-t.mistakes*2);let p=session().players[t.player];p.score+=t.points;p.completed=1;save();render();choice?sayChoice(choice,true):play(['nice'])}
function move(dx,dy){let t=turn(),d=t.data,m=mission();if(t.done)return;let x=d.x+dx,y=d.y+dy;if(d.grid[y]?.[x]!==0){toast('A wall! Try another way.');return}d.x=x;d.y=y;const goal=C.MAZE_EXITS.findIndex(e=>e.x===x&&e.y===y);if(goal>=0){let exit=d.exits[goal];if(exit===m.target){complete(exit);return}if(!d.visitedWrong.includes(exit)){d.visitedWrong.push(exit);t.mistakes++;toast('Try another path.');}sayChoice(exit)}save();render()}
function decorate(index,id){let m=mission(),d=turn().data;if(turn().done||d.placed.includes(index))return;if(!id){toast('Choose a decoration first.');play(['pick']);return}if(id!==m.recipe[index]){mistake('Try a different decoration.',id);return}d.placed.push(index);if(d.placed.length===m.recipe.length)complete(id);else{save();render();sayChoice(id)}}
function paint(part){let d=turn().data;if(turn().done)return;if(!d.selected){toast('Pick a color first.');play(['flagpick']);return}let expected=part==='background'?'white':'red';if(d.selected!==expected){mistake('Try another color.',d.selected);return}d[part]=expected;if(d.background&&d.circle)complete(d.selected);else{save();render();sayChoice(d.selected)}}
function nextTurn(){let s=session();if(!turn().done)return;stopVoice();if(s.index===s.turns.length-1){s.finished=true;s.finishedAt=Date.now();let r=record();if(!r.history.some(h=>h.id===s.id))r.history.unshift({id:s.id,format:C.FORMAT,finishedAt:s.finishedAt,players:s.players.map(p=>({...p}))});r.history=r.history.slice(0,10);save();view='result';render();play(['all'])}else{s.index++;save();render();announce()}}
function renderResult(){let s=session(),sorted=s.players.map((p,i)=>({...p,i})).sort((a,b)=>b.score-a.score),best=sorted[0].score;app.innerHTML=`<section class="result"><span class="pill">ADVENTURE COMPLETE</span><h1>Great teamwork! 🏆</h1><p>Everyone had a turn. You helped Maru!</p><div class="results-grid player-results">${sorted.map(p=>`<article class="result-player ${p.score===best?'winner':''}">${avatar(p.i)}<div><h3>${esc(p.name)}</h3><small>1 / 1 mission</small></div><strong>${p.score}<small> / 10</small></strong></article>`).join('')}</div><div class="memory-strip">${['spring','summer','autumn','winter'].map(k=>`<button data-memory="${k}" aria-label="Listen to ${k}">${item(k)}<span>🔊 ${C.ITEMS[k].label}</span></button>`).join('')}</div><div class="result-actions"><button class="primary" id="replay">↻ Play again</button><button class="secondary" id="edit-players">☻ Set up players</button><button class="secondary" id="copy-game">↗ Copy game link</button></div><p class="class-save-note">Your game is saved on this device.</p></section>`;app.querySelector('#replay').onclick=startGame;app.querySelector('#edit-players').onclick=goSetup;app.querySelector('#copy-game').onclick=copyGameLink;app.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>play(['fact:maze-'+b.dataset.memory],true))}
document.querySelector('#music').onclick=()=>{musicEnabled=!musicEnabled;music.setEnabled(musicEnabled);savePreferences();render()};
document.querySelector('#home').onclick=goSetup;document.querySelector('#classes').onclick=goSetup;document.querySelector('#sound').onclick=()=>{voice=!voice;if(!voice)stopVoice();savePreferences();render();if(voice)play(['voice'])};document.querySelector('#reset').onclick=()=>{if(!cloudReady)return;const target=classId;confirmBox('Reset this game?','Clear this game’s scores and history. Keep the player names. Other games keep their records.','Reset this game',()=>{let r=record(target);r.session=null;r.history=[];delete r.previousSession;save();setupNames=null;view='setup';render();toast('Ready for a fresh game.')})};document.querySelector('#confirm-no').onclick=()=>{pendingAction=null;document.querySelector('#confirm-dialog').close()};document.querySelector('#confirm-yes').onclick=()=>{let fn=pendingAction;pendingAction=null;document.querySelector('#confirm-dialog').close();fn?.()};document.querySelector('#confirm-dialog').addEventListener('cancel',()=>pendingAction=null);
document.addEventListener('keydown',e=>{if(view!=='game'||!turn().called||turn().done||mission().type!=='maze'||document.querySelector('dialog[open]')||e.target.matches('input,textarea'))return;let delta={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0],w:[0,-1],s:[0,1],a:[-1,0],d:[1,0]}[e.key];if(delta){e.preventDefault();move(...delta)}});
function renderLoading(){app.innerHTML=`<section class="cloud-loading"><span>☁️</span><h1>${cloudError?'Let’s reconnect.':'Loading your game…'}</h1><p>${cloudError?'Connect to the internet to load the latest game and scores.':'Your adventure travels with you.'}</p>${cloudError?'<button class="primary" id="cloud-retry">Try again</button><a class="secondary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in</a>':''}</section>`;app.querySelector('#cloud-retry')?.addEventListener('click',bootCloud)}
function syncBadge(state){cloudState=state;const b=document.querySelector('#cloud-status');b.dataset.state=state;b.textContent={loading:'Loading…',saving:'Saving…',saved:'✓ Saved on this device',offline:'☁ Offline · Retry',conflict:'☁ Review sync'}[state]||'☁ Cloud';}
function chooseRoom(){const url=new URL(location.href),requested=url.searchParams.get('room');let remembered;try{remembered=localStorage.getItem('maru-player-room')}catch{}const id=C.isRoom(requested)?requested:C.isRoom(remembered)?remembered:'play-'+crypto.randomUUID().replaceAll('-','');url.searchParams.set('room',id);history.replaceState(null,'',url);try{localStorage.setItem('maru-player-room',id)}catch{}return id;}
async function bootCloud(){cloudError='';view='loading';render();syncBadge('loading');try{classId=chooseRoom();await cloud.loadClass(classId,true);cloudReady=true;setupNames=null;view='setup';render();cloud.flush().catch(()=>{});}catch(e){cloudError=e.message;render();syncBadge('offline')}}
cloud=MaruCloud({onRecords:incoming=>{Object.assign(records,incoming);},onState:syncBadge,onConflict:()=>toast('This game changed on another computer. Tap Review sync.')});
document.querySelector('#cloud-status').onclick=async()=>{const id=cloud.conflictId();if(id){confirmBox('Load the latest game?','Another computer saved a newer game. Load it to continue. This device’s earlier copy will be kept as a backup.','Load cloud copy',async()=>{try{await cloud.resolveConflict(id);classId=id;setupNames=null;view='setup';render()}catch{toast('Reconnect to load the cloud copy.')}});return}if(!cloudReady){bootCloud();return}try{await cloud.flush();toast('Saved on this device.')}catch{toast('Still offline. Your changes are waiting to sync.')}};
const observer=new ResizeObserver(fit);observer.observe(app);observer.observe(document.querySelector('#viewport'));document.fonts?.ready.then(fit);bootCloud();
